  <style>
    /* critical: layout shell for header/hero — Hausmarke */
    body{margin:0;font-family:'Alegreya Sans',ui-sans-serif,system-ui,-apple-system,Segoe UI,sans-serif;background:#F1E8D7;color:#26324B;}
    body > header{display:block;padding:12px 18px;}
    .nav{display:flex;align-items:center;gap:12px;}
    .logo{display:inline-flex;align-items:center;gap:8px;font-weight:600;text-decoration:none;color:#26324B;}
    .hero{padding:48px 18px 32px;max-width:1100px;margin:0 auto;}
    body.page-home .hero{padding:48px 0 32px;max-width:none;margin:0;}
    h1{margin:0 0 12px;font-family:'Vollkorn',Georgia,serif;font-weight:700;font-size:2rem;line-height:1.2;}
    p{margin:0 0 18px;}
    .btn-primary{display:inline-flex;align-items:center;justify-content:center;gap:6px;padding:12px 18px;background:#E8A61C;color:#26324B;border:2px solid #26324B;border-radius:3px;text-decoration:none;font-weight:600;box-shadow:3px 4px 0 rgba(38,50,75,.16);}
  </style>


  <style>
    /* The letterhead line: a firm 2px ink rule under the whole header. */
    html body > header{
      background: var(--bone, #F1E8D7);
      border-bottom: 2px solid var(--ink, #26324B);
    }
    /* Wordmark: Vollkorn, ink, with the accent dot stamped in amber. */
    body > header .brand .word{
      font-family: var(--serif, 'Vollkorn', Georgia, serif);
      font-weight: 700;
    }
    body > header .brand .brand-dot{ color: var(--brass, #E8A61C); }
    /* Nav links: Alegreya Sans 500, ink; current page gets the 2px amber
       underline (zimun.css already reserves the transparent border slot,
       so nothing shifts). */
    body > header .public-nav-desktop a:not(.menu-public__auth),
    body > header .menu a{
      font-family: var(--sans, 'Alegreya Sans', sans-serif);
      font-weight: 500;
      font-size: 15px;
      color: var(--ink, #26324B);
      border-bottom-width: 2px;
    }
    body > header .public-nav-desktop a:not(.menu-public__auth)[aria-current="page"],
    body > header .menu a[aria-current="page"]{
      border-bottom-color: var(--brass, #E8A61C);
    }
    /* Login: a stamped paper button — 2px ink border, hard offset shadow,
       pressed flat on hover like type meeting the platen. */
    body > header .menu-public__auth{
      background: var(--card, #FBF8F0);
      border: 2px solid var(--ink, #26324B);
      border-radius: 3px;
      box-shadow: var(--card-shadow, 3px 4px 0 rgba(38, 50, 75, 0.16));
      font-family: var(--sans, 'Alegreya Sans', sans-serif);
      font-weight: 600;
    }
    body > header .menu-public__auth:hover,
    body > header .menu-public__auth:focus-visible{
      background: var(--card, #FBF8F0);
      transform: translate(2px, 2px);
      box-shadow: none;
    }
  </style>



