<script>
(function () {
  var root = document.documentElement;
  if (!root || !root.style || typeof window.getComputedStyle !== 'function') return;

  // The bottom bar only. The settings modal is fixed and nearly full height,
  // and reserving room for THAT would push every page down by most of a
  // screen while a dialog the visitor opened deliberately is on top of it.
  var SELECTOR = '#klaro .cookie-notice:not(.cookie-modal-notice)';

  var visibleStrip = function () {
    var el = document.querySelector(SELECTOR);
    if (!el) return null;
    var style = window.getComputedStyle(el);
    if (style.position !== 'fixed') return null;
    if (style.display === 'none' || style.visibility === 'hidden') return null;
    var box = el.getBoundingClientRect();
    if (box.width < 10 || box.height < 10) return null;
    return el;
  };

  var sizer = typeof ResizeObserver === 'function' ? new ResizeObserver(function () { schedule(); }) : null;
  var watched = null;
  var pending = false;

  // Every caller below goes through here. `publish` reads geometry, which
  // forces a reflow, and the mutation observer fires for every node the
  // booking page's own scripts add while they fill in slots — measuring once
  // per animation frame instead of once per mutation keeps that off the
  // critical path, and the answer cannot change more often than a frame.
  function schedule() {
    if (pending) return;
    pending = true;
    var run = function () { pending = false; publish(); };
    if (typeof window.requestAnimationFrame === 'function') window.requestAnimationFrame(run);
    else window.setTimeout(run, 16);
  }

  function publish() {
    var el = visibleStrip();
    var reserved = 0;
    if (el) {
      var box = el.getBoundingClientRect();
      // +2: the page then ends two pixels ABOVE the strip rather than exactly
      // against it, so a sub-pixel layout does not put the last control's
      // final row back under the edge.
      reserved = Math.max(0, Math.ceil(window.innerHeight - box.top) + 2);
    }
    root.style.setProperty('--consent-strip-height', reserved + 'px');
    if (sizer && watched !== el) {
      if (watched) sizer.unobserve(watched);
      if (el) sizer.observe(el);
      watched = el;
    }
  }

  // Klaro mounts whenever it is ready and unmounts the bar once a choice is
  // stored, so this watches for both rather than measuring once.
  var observer = new MutationObserver(schedule);
  var start = function () {
    publish();
    observer.observe(document.body, { childList: true, subtree: true });
  };
  if (document.body) start();
  else document.addEventListener('DOMContentLoaded', start);
  window.addEventListener('resize', schedule);
  window.addEventListener('orientationchange', schedule);
  // The notice's own text re-wraps when the web fonts land, which changes how
  // tall it is after everything else has settled.
  if (document.fonts && document.fonts.ready && document.fonts.ready.then) {
    document.fonts.ready.then(schedule).catch(function () {});
  }
})();
</script>


