// supported way to stop a tag that has already loaded: deleting cookies does
// not stop collection, it just makes the next hit arrive without a client id.
const GA4_DISABLE_FLAG = GA4_MEASUREMENT_ID ? 'ga-disable-' + GA4_MEASUREMENT_ID : null;

// Every cookie scope a _ga* cookie could be sitting on. gtag writes the
// registrable domain by default, so a deletion with no domain= addresses a
// scope the cookie was never in and fails silently.
//
// The derived parent walk is what keeps this correct where no domain is
// configured. A browser rejects Set-Cookie for a domain the page is not under,
// so listing extra scopes cannot touch anyone else's cookie; the last label is
// skipped because a public suffix is never settable.
function ga4CookieScopes() {
  const scopes = [null];  // null = emit no domain= at all (host-only cookie)
  if (GA4_COOKIE_DOMAIN) scopes.push(GA4_COOKIE_DOMAIN);
  const host = window.location.hostname;
  if (host && !/^[\d.]+$/.test(host)) {          // skip bare IPv4: no domain scope
    const parts = host.split('.');
    for (let i = 0; i < parts.length - 1; i++) {
      const parent = parts.slice(i).join('.');
      scopes.push(parent, '.' + parent);
    }
  }
  return scopes.filter((scope, i, all) => all.indexOf(scope) === i);
}

function ga4DeleteCookies() {
  const scopes = ga4CookieScopes();
  document.cookie.split(';').forEach(entry => {
    const name = entry.split('=')[0].trim();
    // The `_ga` prefix covers `_ga` (client id), `_ga_<STREAM>` (the GA4
    // session cookie, the one that actually survived), `_gat*` and `_gac_*`.
    // `_gid` is the older id and may still be present.
    if (!name || !(name.startsWith('_ga') || name.startsWith('_gid'))) return;
    scopes.forEach(domain => {
      document.cookie = name + '=;expires=Thu, 01 Jan 1970 00:00:00 GMT;path=/'
        + (domain ? ';domain=' + domain : '');
    });
  });
}

// What GA4 may learn about the URL: origin and path, never the query string
// or fragment. Built from the parsed location, not by removing known
// parameter names, so a parameter added later cannot leak by omission. Passed
// on config, which makes it the value for every event on the page.
function ga4PageFields() {
  const fields = { page_location: window.location.origin + window.location.pathname };
  if (document.referrer) {
    try {
      const ref = new URL(document.referrer);
      fields.page_referrer = ref.origin + ref.pathname;
    } catch (e) {
      fields.page_referrer = '';
    }
  }
  return fields;
}

// Everything `config` is handed: the URL fields above plus two pins that hold
// regardless of the property's own settings — no Google Signals, no
// advertising personalisation. The privacy policy describes web analytics and
// nothing else.
function ga4ConfigFields() {
  return Object.assign(ga4PageFields(), {
    allow_google_signals: false,
    allow_ad_personalization_signals: false,
  });
}

function enableGA4() {
  if (!GA4_MEASUREMENT_ID) return;

  // Clear the opt-out FIRST. A previous withdrawal set it, gtag checks it on
  // every hit, and a stale `true` would silently swallow everything this
  // re-consent is meant to switch back on.
  if (GA4_DISABLE_FLAG) window[GA4_DISABLE_FLAG] = false;

  // Idempotent past this point. Klaro calls onAccept on every applyConsents
  // — modal save, re-consent, not only the first accept — and gtag.js is
  // already in the document from the first one. Clearing the flag above is
  // the whole re-arm: gtag checks it on every hit. Re-running config here
  // would send another page_view for a page viewed once; a second <script>
  // would do the same.
  if (ga4Injected) return;
  ga4Injected = true;

  // Insert the GA4 gtag script dynamically
  const script = document.createElement('script');
  script.src = 'https://www.googletagmanager.com/gtag/js?id=' + GA4_MEASUREMENT_ID;
  script.async = true;
  document.head.appendChild(script);

  window.dataLayer = window.dataLayer || [];
  function gtag(){ dataLayer.push(arguments); }
  window.gtag = gtag;
  gtag('js', new Date());
