  gtag('config', GA4_MEASUREMENT_ID, ga4ConfigFields());
}

function disableGA4() {
  // Order matters: silence the loaded tag before clearing its cookies, so it
  // cannot mint a fresh client id in the gap between the two.
  if (GA4_DISABLE_FLAG) window[GA4_DISABLE_FLAG] = true;
  ga4DeleteCookies();
