    <script>
      (function() {
        // Every .menu-dropdown in this file must be listed here or its
        // trigger is inert: the submenu is display:none until this handler
        // adds .is-open, and no stylesheet opens it on :hover — the
        // .menu-scoped hover rule in css/zimun.css does not reach these,
        // which sit in .nav / .public-nav-desktop. #authLangDropdown was
        // added in 26848bab (2026-06-29) and not listed here, so the
        // signed-in language menu did nothing on desktop for ten weeks
        // (owner 2026-09-07; register G18).
        // A suite test keeps this list complete; see the register entry.
        const dropdowns = [
          document.getElementById('manageDropdown'),
          document.getElementById('publicLangDropdown'),
          document.getElementById('authLangDropdown'),
          document.getElementById('userMenu'),
        ].filter(Boolean);

        // Mount the page-TOC rail at <body> root so position: fixed reads
        // viewport coords, not whatever ancestor has a transform applied.
        const tocRail = document.querySelector('.page-toc-rail');
        if (tocRail && tocRail.parentElement !== document.body) {
          document.body.appendChild(tocRail);
        }

        if (!dropdowns.length) return;

        // ``.menu-trigger`` covers the regular nav dropdowns; ``.user-trigger``
        // is the avatar button — same toggle behaviour, different visual class.
        const findTrigger = (dd) =>
          dd.querySelector('.menu-trigger, .user-trigger');

        const closeOne = (dd) => {
          const trigger = findTrigger(dd);
          dd.classList.remove('is-open');
          trigger?.setAttribute('aria-expanded', 'false');
        };

        const closeAll = () => {
          dropdowns.forEach(closeOne);
        };

        dropdowns.forEach((dd) => {
          const trigger = findTrigger(dd);
          if (trigger?.tagName === 'BUTTON') {
            trigger.addEventListener('click', (e) => {
              e.stopPropagation();
              const isOpen = dd.classList.contains('is-open');
              closeAll();
              if (!isOpen) {
                dd.classList.add('is-open');
                trigger.setAttribute('aria-expanded', 'true');
              }
            });
          } else if (trigger?.tagName === 'A') {
            // On touch / no-hover devices the desktop ``:hover`` rule never
            // fires, so tapping the parent ``<a>`` would navigate before the
            // submenu has a chance to open — the operator can never reach
            // sub-items like "Analytics" or "History". First tap on a
            // no-hover device opens the submenu (preventDefault); a second
            // tap, with the submenu already open, navigates as the href
            // would. On desktop with hover this listener is a no-op.
            trigger.addEventListener('click', (e) => {
              const noHover = window.matchMedia
                && window.matchMedia('(hover: none)').matches;
              if (!noHover) return;
              if (dd.classList.contains('is-open')) return;
              e.preventDefault();
              e.stopPropagation();
              closeAll();
              dd.classList.add('is-open');
              trigger.setAttribute('aria-expanded', 'true');
            });
          }
        });

        document.addEventListener('click', (e) => {
          const insideAny = dropdowns.some((dd) => dd.contains(e.target));
          if (!insideAny) closeAll();
        });

        document.addEventListener('keydown', (e) => {
          if (e.key === 'Escape') closeAll();
        });
      })();
    </script>
