      <script>
    // mobile menu toggle — only the hamburger now needs this. Authenticated
    // users never render a hamburger; the avatar's .user-menu dropdown is
    // their only mobile menu surface, and that dropdown is wired entirely
    // through the existing nav-dropdown click handler in shared_navigation.
    const btn = document.getElementById('menuToggle');
    const menu = document.getElementById('mainMenu');
    btn?.addEventListener('click', () => {
      const open = menu.classList.toggle('open');
      btn.setAttribute('aria-expanded', String(open));
    });
    // settings navigation toggle (mobile)
    const navToggle = document.getElementById('settingsNavToggle');
    const navWrapper = document.getElementById('settingsNavWrapper');
    const navLinks = navWrapper?.querySelectorAll('a') || [];
    const navBackdrop = document.getElementById('settingsNavBackdrop');
    const mobileMq = window.matchMedia('(max-width: 768px)');

    const closeMobileNav = () => {
      navWrapper?.classList.remove('open');
      navBackdrop?.classList.remove('show');
      navToggle?.setAttribute('aria-expanded', 'false');
      document.body.classList.remove('settings-nav-open');
    };

    const openMobileNav = () => {
      navWrapper?.classList.add('open');
      navBackdrop?.classList.add('show');
      navToggle?.setAttribute('aria-expanded', 'true');
      document.body.classList.add('settings-nav-open');
    };

    const syncNavMode = () => {
      if (!navWrapper) return;
      if (mobileMq.matches) {
        closeMobileNav();
      } else {
        navWrapper.classList.remove('open');
        navBackdrop?.classList.remove('show');
        navToggle?.setAttribute('aria-expanded', 'false');
        document.body.classList.remove('settings-nav-open');
      }
    };

    navToggle?.addEventListener('click', () => {
      const expanded = navToggle.getAttribute('aria-expanded') === 'true';
      expanded ? closeMobileNav() : openMobileNav();
    });

    navBackdrop?.addEventListener('click', closeMobileNav);
    navLinks.forEach(link => link.addEventListener('click', closeMobileNav));

    mobileMq.addEventListener?.('change', syncNavMode);
    syncNavMode();

    /* The personal menu's open/close lives in ONE place: the dropdown handler in
       shared_navigation.html, which already covers #userMenu alongside the three
       other dropdowns, closes them all on an outside click and closes them on
       Escape. A second copy used to live here -- its own click listener on the
       same .user-trigger and its own outside-click close -- and the two undid
       each other (BUG-740): the first added `is-open`, this one read the class
       it had just set and toggled it straight back off, so a click netted out to
       "not open" and left aria-expanded="false" on a menu the stylesheet was
       showing anyway through `:focus-within`. `e.stopPropagation()` in the first
       handler could not prevent it, because that stops bubbling and not a second
       listener on the SAME element -- which needs stopImmediatePropagation.
       Deleted rather than deduplicated: this copy had no Escape handling and
       closed only #userMenu, so the one that survives is strictly the better of
       the two. */

    // Language selectors — both the desktop nav (#langSelect) and the
    // mobile user-menu (#userMenuLangSelect) share class .lang-select.
    // Binding by class covers both without the mobile menu silently
    // losing its handler.
    // Options rendered by shared_navigation.html carry data-url from
    // switch_language_url (path-prefixed on in-scope pages, ?lang= on
    // out-of-scope pages) — prefer it. Selects without data-url (the
    // booking page's own #bookingLangSelect keeps its markup) fall back
    // to the legacy ?lang= navigation unchanged.
    document.querySelectorAll('.lang-select').forEach((sel) => {
      sel.addEventListener('change', (e) => {
        const selected = e.target.selectedOptions && e.target.selectedOptions[0];
        if (selected && selected.dataset && selected.dataset.url) {
          window.location.href = selected.dataset.url;
          return;
        }
        const url = new URL(window.location.href);
        url.searchParams.set('lang', e.target.value);
        window.location.href = url.toString();
      });
    });

    // current year (footer markup may be omitted on minimal pages like /termin/r/{id})
{
  const yearEl = document.getElementById('year');
  if (yearEl) yearEl.textContent = new Date().getFullYear();
}

    // --- Per-page TOC rail ---
    // Activated when <body data-page-toc-target="<selector>"> is set.
    // Auto-scrapes <h2> headings inside the matched container, slugifies
    // missing ids, and renders a vertical list in `.page-toc-rail`.
    // IntersectionObserver tracks which section is in view.
    (function mountPageTocRail(){
      const rail = document.querySelector('.page-toc-rail');
      if (!rail) return;
      const targetSel = document.body.dataset.pageTocTarget;
      if (!targetSel) return;
      const container = document.querySelector(targetSel);
      if (!container) return;
      const headings = Array.from(container.querySelectorAll('h2'));
      if (headings.length < 2) return; // not enough to justify a TOC

      const slugify = (s) => (s || '').toLowerCase()
        .replace(/[^a-z0-9\s-]/g, '')
        .trim()
        .replace(/\s+/g, '-')
        .slice(0, 60) || 'section';
      const usedIds = new Set();
      const items = headings.map((h) => {
        let id = h.id;
        if (!id) {
          id = slugify(h.textContent);
          let unique = id, n = 2;
          while (usedIds.has(unique) || document.getElementById(unique)) {
            unique = id + '-' + n;
            n += 1;
          }
          id = unique;
          h.id = id;
        }
        usedIds.add(id);
        return { id, label: h.textContent.trim() };
      });

      const head = document.createElement('div');
      head.className = 'page-toc-rail__head';
      head.textContent = (document.documentElement.lang || 'en').startsWith('de')
        ? 'Auf dieser Seite' : 'On this page';
      rail.appendChild(head);
      const links = items.map(({ id, label }) => {
        const a = document.createElement('a');
        a.className = 'page-toc-rail__link';
        a.href = '#' + id;
        a.dataset.tocFor = id;
        a.textContent = label;
        rail.appendChild(a);
        return a;
      });
      rail.hidden = false;

      const byId = new Map(items.map((it, i) => [it.id, links[i]]));
      const observer = new IntersectionObserver((entries) => {
        entries.forEach((entry) => {
          if (!entry.isIntersecting) return;
          links.forEach((link) => link.classList.remove('is-active'));
          const active = byId.get(entry.target.id);
          if (active) active.classList.add('is-active');
        });
      }, { rootMargin: '-30% 0px -55% 0px', threshold: 0 });
      items.forEach(({ id }) => {
        const el = document.getElementById(id);
        if (el) observer.observe(el);
      });
    })();

    // --- Google Maps: click to load ---
    // Opening a settings page must not, by itself, introduce the visitor to
    // Google. Both the Maps JavaScript API and the ?output=embed iframe send the
    // IP address and user agent to Google before anything is displayed, and the
    // client-side geocoder sends the address the member typed.
    // None of that is necessary to render the page, so it waits for a click —
    // the "two-click" pattern German data-protection authorities have expected
    // for embedded third-party content since long before the Google Fonts
    // judgment (LG München I, 3 O 17493/20).
    //
    // The choice is remembered in sessionStorage, so a member configuring
    // several locations clicks once per session rather than once per page.
    // Storing the visitor's own decision is what TDDDG § 25 Abs. 2 exempts;
    // nothing else is stored here.
    const MAPS_CONSENT_KEY = 'zimun.mapsConsent';
    const mapsConsentGiven = () => {
      try { return sessionStorage.getItem(MAPS_CONSENT_KEY) === '1'; } catch (e) { return false; }
    };
    const rememberMapsConsent = () => {
      try { sessionStorage.setItem(MAPS_CONSENT_KEY, '1'); } catch (e) { /* private mode */ }
    };

    const buildMapConsentCard = (onAccept) => {
      const card = document.createElement('div');
      card.className = 'map-consent';
      card.setAttribute('style', 'display:flex;flex-direction:column;gap:10px;align-items:flex-start;justify-content:center;padding:20px;min-height:200px;border:1px solid var(--border,#d8d8e0);border-radius:16px;background:var(--surface-2,#f6f6f8);');
      const title = document.createElement('strong');
      title.textContent = 'Map not loaded';
      const body = document.createElement('span');
      body.setAttribute('style', 'font-size:0.9rem;line-height:1.45;opacity:0.85;');
      body.textContent = 'The map and the address search are provided by Google Maps. Loading them transmits your IP address to Google. Nothing has been transmitted so far.';
      const button = document.createElement('button');
      button.type = 'button';

      button.className = 'btn-v2';

      button.textContent = 'Load map';
      button.addEventListener('click', () => {
        rememberMapsConsent();
        onAccept();
      });
      card.append(title, body, button);
      return card;
    };

    const initOrgMaps = () => {
      const mapContainers = document.querySelectorAll('.org-map-interactive');
      // Iframe embeds carry their URL in data-map-src precisely so that the
      // browser has nothing to fetch until consent. Never move this back to src.
      const gatedFrames = document.querySelectorAll('iframe[data-map-src]');
      if (!mapContainers.length && !gatedFrames.length) return;

      const activateFrames = () => {
        gatedFrames.forEach((frame) => {
          const url = frame.dataset.mapSrc;
          if (!url || frame.src) return;
          frame.hidden = false;
          frame.src = url;
        });
      };

      if (!mapsConsentGiven()) {
        // The iframe fallback and the interactive container are alternatives in
        // the templates, so at most one of these branches has work to do.
        gatedFrames.forEach((frame) => {
          frame.hidden = true;
          frame.insertAdjacentElement('beforebegin', buildMapConsentCard(() => {
            document.querySelectorAll('.map-consent').forEach((el) => el.remove());
            activateFrames();
            loadOrgMaps();
          }));
        });
        mapContainers.forEach((el) => {
          el.replaceChildren(buildMapConsentCard(() => {
            document.querySelectorAll('.map-consent').forEach((el2) => el2.remove());
            mapContainers.forEach((c) => c.replaceChildren());
            activateFrames();
            loadOrgMaps();
          }));
        });
        return;
      }

      activateFrames();
      loadOrgMaps();
    };

    const loadOrgMaps = () => {
      const mapContainers = document.querySelectorAll('.org-map-interactive');
      if (!mapContainers.length) return;
      const key = mapContainers[0].dataset.mapsKey;
      if (!key) return;

      if (!window.__orgMapInit) {
        window.__orgMapInit = () => {
          mapContainers.forEach((el) => {
            const lat = parseFloat(el.dataset.lat);
            const lng = parseFloat(el.dataset.lng);
            const center = (!isNaN(lat) && !isNaN(lng)) ? { lat, lng } : { lat: 52.52, lng: 13.405 };
            // The Map ID selects the map's type and style, and comes from
            // configuration (GOOGLE_MAPS_MAP_ID) rather than being hardcoded here.
            // It is allowed to be absent: no Map ID means no cloud styling and a
            // classic marker, i.e. a degraded map rather than a broken one, which
            // is what lets the key and the Map ID be changed in either order.
            const mapId = (el.dataset.mapId || '').trim();
            const mapOptions = {
              center,
              zoom: (!isNaN(lat) && !isNaN(lng)) ? 14 : 5,
              mapTypeControl: false,
              streetViewControl: false,
            };
            if (mapId) mapOptions.mapId = mapId;
            const map = new google.maps.Map(el, mapOptions);
            // Advanced markers REQUIRE a Map ID; without one they throw, so the
            // fallback is the classic marker.
            const placeMarker = (position) => (mapId
              ? new google.maps.marker.AdvancedMarkerElement({ position, map })
              : new google.maps.Marker({ position, map }));
            const moveMarker = (m, position) => {
              if (mapId) { m.position = position; } else { m.setPosition(position); }
            };
            let marker = null;
            if (!isNaN(lat) && !isNaN(lng)) {
              marker = placeMarker(center);
            }
            const readonly = el.dataset.readonly === '1';
            const addressInputSelector = el.dataset.input;
            const searchBtnSelector = el.dataset.search;
            const statusSelector = el.dataset.status;
            const statusEl = statusSelector ? document.querySelector(statusSelector) : null;const payloadSelector = el.dataset.payload;
            const payloadInput = payloadSelector
              ? document.querySelector(payloadSelector)
              : document.getElementById('org_address_payload');
            const writeStatus = (text, state) => {
              if (!statusEl) return;
              statusEl.textContent = text || '';
              statusEl.dataset.state = state || '';
            };
            if (statusEl && !readonly) {
              writeStatus(el.dataset.address ? 'Current: ' + el.dataset.address : '', 'info');
            }
            // A second, iframe-based preview (#org_map_preview_frame) used to be
            // driven from here — including a 52.52,13.405 fallback that embedded
            // a map of central Berlin when the organisation had no address at
            // all. No template has defined that element for a long time, so the
            // code was dead and the fallback unreachable. Removed rather than
            // consent-gated: an interactive map is already on the page.

            const updatePayload = (data) => {
              if (!payloadInput) return;
              try {
                payloadInput.value = JSON.stringify(data || {});
              } catch (_err) {
                console.warn('Unable to store address payload', _err);
              }
            };

            const updateMarker = (loc, formatted, details = {}) => {
              if (!loc) return;
              if (marker) {
                moveMarker(marker, loc);
              } else {
                marker = placeMarker(loc);
              }
              map.setCenter(loc);
              map.setZoom(15);
              if (statusEl && formatted) {
                writeStatus(`Found: ${formatted}`, 'success');
              }
              updatePayload({
                raw: details.raw || formatted || input?.value || '',
                formatted: details.formatted || formatted || '',
                lat: loc.lat ? loc.lat() : loc.lat || null,
                lng: loc.lng ? loc.lng() : loc.lng || null,
                place_id: details.place_id || null,
                city: details.city || null,
                state: details.state || null,
                state_code: details.state_code || null,
                country: details.country || null,
                country_code: details.country_code || null,
                map_url: details.map_url || (formatted ? `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(formatted)}` : null),
                embed_url: details.embed_url || (formatted ? `https://www.google.com/maps?q=${encodeURIComponent(formatted)}&output=embed` : null),
              });
            };
            // Gated on what this block actually needs — an address input and an
            // editable map — and NOT on `google.maps.places`, which is what it
            // used to test. That guard was a leftover from a Places-autocomplete
            // implementation this code no longer contains: everything below uses
            // google.maps.Geocoder. It went unnoticed because a truthy `places`
            // namespace was always present while the library was loaded, and it
            // broke the address search the moment the unused library was dropped —
            // silently, because a failed guard skips rather than throws.
            if (!readonly && addressInputSelector) {
              const input = document.querySelector(addressInputSelector);
              const searchBtn = searchBtnSelector ? document.querySelector(searchBtnSelector) : null;
              const geocoder = new google.maps.Geocoder();
              const runGeocode = (query) => {
                if (!query) return;
                writeStatus('Searching for ' + query + '...', 'info');
                geocoder.geocode({ address: query }, (results, status) => {
                  if (status === 'OK' && results && results.length) {
                    const place = results[0];
                    if (input) input.value = place.formatted_address || query;
                    updateMarker(place.geometry.location, place.formatted_address || query, {
                      raw: query,
                      formatted: place.formatted_address,
                      place_id: place.place_id,
                      city: (() => {
                        const component = (place.address_components || []).find((item) => (item.types || []).includes('locality') || (item.types || []).includes('postal_town') || (item.types || []).includes('administrative_area_level_2'));
                        return component ? (component.long_name || null) : null;
                      })(),
                      state: (() => {
                        const component = (place.address_components || []).find((item) => (item.types || []).includes('administrative_area_level_1'));
                        return component ? (component.long_name || null) : null;
                      })(),
                      state_code: (() => {
                        const component = (place.address_components || []).find((item) => (item.types || []).includes('administrative_area_level_1'));
                        return component ? (component.short_name || null) : null;
                      })(),
                      country: (() => {
                        const component = (place.address_components || []).find((item) => (item.types || []).includes('country'));
                        return component ? (component.long_name || null) : null;
                      })(),
                      country_code: (() => {
                        const component = (place.address_components || []).find((item) => (item.types || []).includes('country'));
                        return component ? (component.short_name || null) : null;
                      })(),
                    });
                  } else {
                    writeStatus('Could not find ' + query, 'error');
                  }
                });
              };

              searchBtn?.addEventListener('click', () => {
                runGeocode(input?.value);
              });
            }
          });
        };
      }

      if (!window.__orgMapsScriptLoading) {
        window.__orgMapsScriptLoading = true;
        const script = document.createElement('script');
        // `places` was requested here and never used — no Autocomplete, no
        // PlacesService, nothing. Dropping it removes a library from the
        // download and, more usefully, removes Places from the set of APIs the
        // browser key has to be authorised for. The key is in the served HTML,
        // so every API it can reach is an API someone else can spend on.
        script.src = `https://maps.googleapis.com/maps/api/js?key=${key}&libraries=marker&callback=__orgMapInit&loading=async`;
        script.async = true;
        script.defer = true;
        document.head.appendChild(script);
      } else if (window.google && window.google.maps) {
        window.__orgMapInit();
      }
    };

    initOrgMaps();

// Klaro renders its banner as role="dialog" with no accessible name, so a
// screen reader announces "dialog" and nothing else — the one thing on the
// page a visitor must act on before anything else. Klaro takes no aria-label
// option and the file is vendored, so name it from the config's own
// consentNotice.title (already translated in all seven locales) once it
// appears. Observer, not a timeout: Klaro mounts whenever it is ready.
{
  const nameKlaroDialog = () => {
    const notice = document.getElementById('klaro-cookie-notice');
    if (!notice || notice.getAttribute('aria-label')) return false;
    const cfg = window.klaroConfig || {};
    const title = cfg.translations?.[cfg.lang]?.consentNotice?.title
      || cfg.translations?.en?.consentNotice?.title;
    if (!title) return false;
    notice.setAttribute('aria-label', title);
    return true;
  };
  if (!nameKlaroDialog()) {
    const observer = new MutationObserver(() => { if (nameKlaroDialog()) observer.disconnect(); });
    observer.observe(document.body, { childList: true, subtree: true });
    // Klaro can also be re-opened later; stop watching once the page settles.
    setTimeout(() => observer.disconnect(), 15000);
  }
}

// consent - Klaro (footer may be omitted on minimal pages like /termin/r/{id})
{
  const link = document.getElementById('manage-consent');
  if (link) {
    link.addEventListener('click', (e) => {
      e.preventDefault();
      if (window.klaro?.show) return window.klaro.show();
      const mgr = window.klaro?.getManager?.();
      if (mgr?.show) mgr.show();
    });
  }
}
</script>








