<script>
/* Idle beat: after real inactivity, at random intervals, the sealed slot in
   the header Siegel yields to the Monokel's eyes for one blink, then seals
   again. Cancels instantly on any activity; never under reduced motion or
   automation. */
(function () {
  var mark = document.querySelector('.hm-siegel[data-hm-idle]');
  if (!mark || navigator.webdriver) return;
  if (window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches) return;
  var IDLE_MS = 45000, last = Date.now(), playing = false, nextBeatAt = schedule();
  function schedule() { return Date.now() + IDLE_MS + 20000 + Math.random() * 50000; }
  function activity() {
    last = Date.now();
    if (playing) stop();
    nextBeatAt = schedule();
  }
  ['pointermove', 'pointerdown', 'keydown', 'scroll', 'touchstart'].forEach(function (ev) {
    addEventListener(ev, activity, { passive: true });
  });
  function stop() { playing = false; mark.classList.remove('hm-peek', 'hm-blink'); }
  function beat() {
    playing = true;
    mark.classList.add('hm-peek');
    setTimeout(function () { if (playing) mark.classList.add('hm-blink'); }, 700);
    setTimeout(function () { if (playing) mark.classList.remove('hm-blink'); }, 850);
    setTimeout(function () { if (playing) mark.classList.add('hm-blink'); }, 1050);
    setTimeout(function () { if (playing) mark.classList.remove('hm-blink'); }, 1200);
    setTimeout(function () { if (playing) { stop(); nextBeatAt = schedule(); } }, 1900);
  }
  setInterval(function () {
    if (playing || document.hidden) return;
    if (Date.now() - last >= IDLE_MS && Date.now() >= nextBeatAt) beat();
  }, 1000);
})();
</script>
